sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  if (isLoading || newValue === oldValue) { return; }
  var HIGH_IMPACT = "1";
  if (newValue === HIGH_IMPACT) {
    g_form.setMandatory('assignment_group', true);
    g_form.setMandatory('assigned_to', true);
    g_form.setMandatory('business_service', true);
    g_form.setVisible('assignment_group', true);
    g_form.setVisible('assigned_to', true);
    g_form.setVisible('business_service', true);
    g_form.addInfoMessage('High Impact incident detected. Assignment Group, Assigned To, and Business Service are now required.');
  } else {
    g_form.setMandatory('assignment_group', false);
    g_form.setMandatory('assigned_to', false);
    g_form.setMandatory('business_service', false);
    g_form.clearMessages();
  }
}

sys_ui_policy.script_true:
function onCondition() {
  g_form.showFieldMsg('priority', 'High Impact: Ensure escalation procedures are followed.', 'info');
}
